sc_cat_item_producer.script:
(function executeProducerScript(current, producer) {
  current.requested_for = gs.getUserID();
  current.source_station = producer.source_station;
  current.destination_station = producer.destination_station;
  current.travel_date = producer.travel_date;
  current.journey_type = producer.journey_type;
  current.ticket_medium = 'digital_qr';
  current.passenger_count = producer.passenger_count;
  current.metro_status = 'pending';
  current.short_description = 'Hyderabad Metro ticket booking';
})(current, producer);
